# Murrelektronik IMPACT67 E DIO8 (DIO8) (art. no. 55089) over EtherNet/IP (enip-io, one
# Class 1 exclusive-owner connection at 10 ms): every channel of the profile.
# Assemblies and bits from the IMPACT67 E handbook, edition 1.8, pp. 73-75.
# Not checked on a unit.
device i67 enip-io ADDR config=110 o2t=35:2 t2o=117:8 rpi_ms=10

# inputs, input byte 0 (pin 4) and 1 (pin 2): a channel set to input
in  i67_di_00               bool i67 in:0.0
in  i67_di_01               bool i67 in:0.1
in  i67_di_02               bool i67 in:0.2
in  i67_di_03               bool i67 in:0.3
in  i67_di_04               bool i67 in:0.4
in  i67_di_05               bool i67 in:0.5
in  i67_di_06               bool i67 in:0.6
in  i67_di_07               bool i67 in:0.7
in  i67_di_10               bool i67 in:1.0
in  i67_di_11               bool i67 in:1.1
in  i67_di_12               bool i67 in:1.2
in  i67_di_13               bool i67 in:1.3
in  i67_di_14               bool i67 in:1.4
in  i67_di_15               bool i67 in:1.5
in  i67_di_16               bool i67 in:1.6
in  i67_di_17               bool i67 in:1.7

# supply diagnosis, input byte 2 (p. 74)
in  i67_ua_missing          bool i67 in:2.1
in  i67_us_low              bool i67 in:2.2
in  i67_ua_low              bool i67 in:2.3

# sensor supply short-circuit per M12 port, input byte 3
in  i67_port_0_sensor_short bool i67 in:3.0
in  i67_port_1_sensor_short bool i67 in:3.1
in  i67_port_2_sensor_short bool i67 in:3.2
in  i67_port_3_sensor_short bool i67 in:3.3
in  i67_port_4_sensor_short bool i67 in:3.4
in  i67_port_5_sensor_short bool i67 in:3.5
in  i67_port_6_sensor_short bool i67 in:3.6
in  i67_port_7_sensor_short bool i67 in:3.7

# output overload per channel, input bytes 4 (pin 4) and 5 (pin 2)
in  i67_do_00_overload      bool i67 in:4.0
in  i67_do_01_overload      bool i67 in:4.1
in  i67_do_02_overload      bool i67 in:4.2
in  i67_do_03_overload      bool i67 in:4.3
in  i67_do_04_overload      bool i67 in:4.4
in  i67_do_05_overload      bool i67 in:4.5
in  i67_do_06_overload      bool i67 in:4.6
in  i67_do_07_overload      bool i67 in:4.7
in  i67_do_10_overload      bool i67 in:5.0
in  i67_do_11_overload      bool i67 in:5.1
in  i67_do_12_overload      bool i67 in:5.2
in  i67_do_13_overload      bool i67 in:5.3
in  i67_do_14_overload      bool i67 in:5.4
in  i67_do_15_overload      bool i67 in:5.5
in  i67_do_16_overload      bool i67 in:5.6
in  i67_do_17_overload      bool i67 in:5.7

# output warning per channel, input bytes 6 (pin 4) and 7 (pin 2)
in  i67_do_00_warning       bool i67 in:6.0
in  i67_do_01_warning       bool i67 in:6.1
in  i67_do_02_warning       bool i67 in:6.2
in  i67_do_03_warning       bool i67 in:6.3
in  i67_do_04_warning       bool i67 in:6.4
in  i67_do_05_warning       bool i67 in:6.5
in  i67_do_06_warning       bool i67 in:6.6
in  i67_do_07_warning       bool i67 in:6.7
in  i67_do_10_warning       bool i67 in:7.0
in  i67_do_11_warning       bool i67 in:7.1
in  i67_do_12_warning       bool i67 in:7.2
in  i67_do_13_warning       bool i67 in:7.3
in  i67_do_14_warning       bool i67 in:7.4
in  i67_do_15_warning       bool i67 in:7.5
in  i67_do_16_warning       bool i67 in:7.6
in  i67_do_17_warning       bool i67 in:7.7

# outputs, output byte 0 (pin 4) and 1 (pin 2): a channel set to output
out i67_do_00               bool i67 out:0.0 safe=false
out i67_do_01               bool i67 out:0.1 safe=false
out i67_do_02               bool i67 out:0.2 safe=false
out i67_do_03               bool i67 out:0.3 safe=false
out i67_do_04               bool i67 out:0.4 safe=false
out i67_do_05               bool i67 out:0.5 safe=false
out i67_do_06               bool i67 out:0.6 safe=false
out i67_do_07               bool i67 out:0.7 safe=false
out i67_do_10               bool i67 out:1.0 safe=false
out i67_do_11               bool i67 out:1.1 safe=false
out i67_do_12               bool i67 out:1.2 safe=false
out i67_do_13               bool i67 out:1.3 safe=false
out i67_do_14               bool i67 out:1.4 safe=false
out i67_do_15               bool i67 out:1.5 safe=false
out i67_do_16               bool i67 out:1.6 safe=false
out i67_do_17               bool i67 out:1.7 safe=false
